  function activeNpcs(){return maps[state.scene].npcs.filter(n=>{if(n.kind!=='jason')return true;if(n.action==='jason')return state.companion!=='Jason';if(n.action==='jasonHome')return state.companion==='Jason'&&state.companionLocation==='home';if(n.action==='jasonBeach')return state.companion==='Jason'&&state.companionLocation==='beach';return true})}
