  function spriteState(el,stateName,duration=0){el.classList.remove('normal','attack','hit','down');el.classList.add(stateName);if(duration)setTimeout(()=>{if(el.isConnected&&!el.classList.contains('down')){el.classList.remove('attack','hit');el.classList.add('normal')}},duration)}
  function battleAction(action){const b=state.battle;if(!b||b.turnLocked)return;if(action==='run'){endBattle('Le Slaymatch s’arrête là. Aucun drame : on pourra recommencer.');return}b.turnLocked=true;spriteState(UI.playerSprite,'attack',600);if(action==='pose'){const success=Math.random()<.8;if(success){b.enemy.charmed=true;b.captureBonus=1.3;UI.battleText.textContent='Sexyflex demande : « T’as vu mes pecs ? » '+b.enemy.name+' est sous le charme !'}else UI.battleText.textContent=b.enemy.name+' détourne le regard. Le charme échoue !';updateBattle();setTimeout(()=>enemyTurn(b),750);return}const p=state.team[0],power=50,critical=Math.random()<.5,variance=.85+Math.random()*.15;let damage=Math.floor((((2*p.level/5+2)*power*p.attack/b.enemy.defense)/50+2)*variance*(critical?1.5:1));damage=Math.max(1,damage);b.enemy.hp=Math.max(0,b.enemy.hp-damage);spriteState(UI.enemySprite,b.enemy.hp<=0?'down':'hit',b.enemy.hp<=0?0:500);UI.battleText.textContent='« Ma main dans ta gueule ! » '+damage+' dégâts'+(critical?' — COUP CRITIQUE !':' !');updateBattle();if(b.enemy.hp<=0){setTimeout(()=>endBattle('Victoire ! '+b.enemy.trainer+' applaudit la puissance de Sexyflex.'),1100);return}setTimeout(()=>enemyTurn(b),750)}
